"""Roman numeral parsing. Implement roman_to_int so the tests pass."""

def roman_to_int(s):
    """Convert an uppercase Roman numeral string to its integer value.
    Must handle subtractive forms (IV=4, IX=9, XL=40, XC=90, CD=400, CM=900)."""
    roman_values = {
        'I': 1, 'V': 5, 'X': 10, 'L': 50,
        'C': 100, 'D': 500, 'M': 1000
    }
    total = 0
    prev_value = 0

    for char in reversed(s):
        value = roman_values[char]
        if value < prev_value:
            total -= value
        else:
            total += value
        prev_value = value

    return total
